-- Actual synthetic collections/refunds, original source, reservation and crash reconciliation; isolated by rollback.
begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
create function pg_temp.id(n integer)returns uuid language sql immutable as $$select('d2090009-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
create function pg_temp.claim(n integer)returns text language sql as $$select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.id(n),'session_id',pg_temp.id(n+10),'role','authenticated','user_metadata',jsonb_build_object('owner',true,'billing',true,'discount_approved',true))::text,true)$$;
insert into auth.users(id,email,email_confirmed_at)select pg_temp.id(n),'synthetic-m6-009-payment-'||n||'@example.test',now()from generate_series(1,3)n;
insert into auth.sessions(id,user_id)select pg_temp.id(n+10),pg_temp.id(n)from generate_series(1,3)n;
insert into public.doctor_candidate_admissions(user_id,purpose,evidence_ref,valid_until)select pg_temp.id(n),'synthetic_fixture','disposable-m6-006:'||n,clock_timestamp()+interval'2 hours'from generate_series(1,3)n;
insert into public.doctor_profiles(user_id,display_name)values(pg_temp.id(1),'Synthetic billing doctor A'),(pg_temp.id(2),'Synthetic billing doctor B');
insert into public.practices(id,owner_user_id,name)values(pg_temp.id(21),pg_temp.id(1),'Synthetic price practice A'),(pg_temp.id(22),pg_temp.id(2),'Synthetic price practice B');
insert into public.locations(id,practice_id,name,timezone)values(pg_temp.id(31),pg_temp.id(21),'Synthetic clinic A','Etc/UTC'),(pg_temp.id(32),pg_temp.id(22),'Synthetic clinic B','Etc/UTC');
insert into public.memberships(id,practice_id,user_id,capabilities)values(pg_temp.id(301),pg_temp.id(21),pg_temp.id(3),array['patients.read','appointments.write']);
insert into public.membership_locations(practice_id,membership_id,location_id)values(pg_temp.id(21),pg_temp.id(301),pg_temp.id(31));
insert into public.patient_identities(id)values(pg_temp.id(41)),(pg_temp.id(42));
insert into public.practice_patients(id,practice_id,patient_identity_id,display_name,created_location_id,created_by)values(pg_temp.id(51),pg_temp.id(21),pg_temp.id(41),'Synthetic billing patient A',pg_temp.id(31),pg_temp.id(1)),(pg_temp.id(52),pg_temp.id(22),pg_temp.id(42),'Synthetic billing patient B',pg_temp.id(32),pg_temp.id(2));
insert into public.appointments(id,practice_id,doctor_user_id,location_id,patient_id,starts_at,ends_at,timezone,location_name,created_by)values(pg_temp.id(61),pg_temp.id(21),pg_temp.id(1),pg_temp.id(31),pg_temp.id(51),now()+interval'1 day',now()+interval'1 day 20 minutes','Etc/UTC','Synthetic clinic A',pg_temp.id(1)),(pg_temp.id(62),pg_temp.id(22),pg_temp.id(2),pg_temp.id(32),pg_temp.id(52),now()+interval'1 day',now()+interval'1 day 20 minutes','Etc/UTC','Synthetic clinic B',pg_temp.id(2));
insert into public.appointments(id,practice_id,doctor_user_id,location_id,patient_id,starts_at,ends_at,timezone,location_name,created_by)values(pg_temp.id(63),pg_temp.id(21),pg_temp.id(1),pg_temp.id(31),pg_temp.id(51),now()+interval'1 day 1 hour',now()+interval'1 day 1 hour 20 minutes','Etc/UTC','Synthetic clinic A',pg_temp.id(1));
set constraints all immediate;set constraints all deferred;
create temporary table results(name text primary key,value jsonb);grant all on results to authenticated;
create function pg_temp.value(k text,field text)returns uuid language sql as $$select(value->>field)::uuid from results where name=k$$;
create function pg_temp.price(service uuid,revision integer,minor text,key integer,currency text default'EGP')returns jsonb language sql security invoker as $$select public.doctor_write_service_price(pg_temp.id(21),pg_temp.id(31),service,revision,'Synthetic visit service',minor,currency,2,pg_temp.id(key))$$;
create function pg_temp.charge(price uuid,quantity integer,key integer,charge uuid default null,revision integer default 0,visit_revision integer default 1)returns jsonb language sql security invoker as $$select public.doctor_write_visit_charge(pg_temp.id(21),pg_temp.id(31),pg_temp.id(61),visit_revision,pg_temp.id(51),price,quantity,charge,revision,'Synthetic attributable charge/correction',pg_temp.id(key))$$;
set local role authenticated;select pg_temp.claim(1);
insert into results values('price1',pg_temp.price(null,0,'29900',701)),('charge1','{}'::jsonb);
update results set value=pg_temp.charge(pg_temp.value('price1','id'),5,702)where name='charge1';
reset role;
create function pg_temp.report(metric text default'charges',page integer default 1,status text default'all',currency text default null,exponent integer default null,since timestamptz default null,until_time timestamptz default null)returns jsonb language sql security invoker as $$select public.doctor_practice_financial_report(pg_temp.id(21),null,since,until_time,status,metric,currency,exponent,page)$$;
create function pg_temp.group_value(metric text,unit text default'EGP',exponent integer default 2)returns text language sql security invoker as $$select g->>metric from jsonb_array_elements(pg_temp.report()->'totals')g where g->>'currency'=unit and(g->>'currency_exponent')::integer=exponent$$;
create function pg_temp.prepare(kind text,minor text,key integer,original uuid default null)returns jsonb language sql security invoker as $$select public.doctor_prepare_practice_payment(pg_temp.id(21),pg_temp.id(31),kind,pg_temp.value('charge1','id'),original,minor,'Synthetic reporting collection/refund',pg_temp.id(key))$$;
create function pg_temp.advance(name text,revision integer,action text,key integer,outcome text default null)returns jsonb language sql security invoker as $$select public.doctor_advance_practice_payment(pg_temp.id(21),pg_temp.id(31),pg_temp.value(name,'id'),revision,action,outcome,pg_temp.id(key))$$;
set local role authenticated;select pg_temp.claim(1);
insert into results values('collection',pg_temp.prepare('collection','49900',703));
select lives_ok($$select pg_temp.advance('collection',1,'dispatch',704,'accepted')$$,'owned synthetic collection accepted independently of ledger');
insert into results values('posted',pg_temp.advance('collection',2,'reconcile',705));
insert into results values('refund',pg_temp.prepare('refund','30000',706,(select(value#>>'{entry,id}')::uuid from results where name='posted')));
select lives_ok($$select pg_temp.advance('refund',1,'dispatch',707,'accepted')$$,'refund synthetic acceptance is explicit');
insert into results values('reversal',pg_temp.advance('refund',2,'reconcile',708));
insert into results values('unknown',pg_temp.prepare('collection','20000',709));
select lives_ok($$select pg_temp.advance('unknown',1,'dispatch',710,'accepted')$$,'delayed reconciliation retains unknown reservation');
insert into results values('pendingRefund',pg_temp.prepare('refund','1000',711,(select(value#>>'{entry,id}')::uuid from results where name='posted')));
select is(pg_temp.group_value('charges_minor'),'149500','issued charge counted once');
select is(pg_temp.group_value('collections_minor'),'49900','collection report matches immutable entry');
select is(pg_temp.group_value('refunds_minor'),'30000','refund report matches original-linked reversal');
select is(pg_temp.group_value('outstanding_minor'),'129600','outstanding uses posted collection less refund only');
select is(pg_temp.group_value('reserved_collection_minor'),'20000','unknown collection remains reserved and is not paid');
select is(pg_temp.group_value('reserved_refund_minor'),'1000','prepared refund is reserved, not a posted reversal');
select is(pg_temp.group_value('unknown_count'),'1','unknown status remains distinct from posted');
select is(pg_temp.group_value('discrepancy_count'),'0','consistent ledger has no fabricated discrepancy');
select is(pg_temp.report('unknown')->'items'->0->>'source_revision','2','unknown total traces exact historical event');
select is(public.doctor_practice_financial_source(pg_temp.id(21),'intent_event',pg_temp.value('unknown','id'),2)->'record'->>'state','unknown','exact unknown event projection is read only');
insert into results values('unknownPosted',pg_temp.advance('unknown',2,'reconcile',712));
select is(public.doctor_practice_financial_source(pg_temp.id(21),'intent_event',pg_temp.value('unknown','id'),2)->'record'->>'state','unknown','old event link never becomes current posted event');
select is(public.doctor_practice_financial_source(pg_temp.id(21),'intent_event',pg_temp.value('unknown','id'),2)->'details'->>'current_event_revision','3','current revision is separate from immutable requested event');
select is(public.doctor_practice_financial_source(pg_temp.id(21),'ledger',(select(value#>>'{entry,id}')::uuid from results where name='reversal'))->'details'->>'original_receipt_label','SYN-00000001','refund trace preserves original scoped synthetic receipt');
insert into results values('price2',pg_temp.price(pg_temp.value('price1','service_id'),1,'200000',713));
insert into results values('charge2',pg_temp.charge(pg_temp.value('price2','id'),1,714,pg_temp.value('charge1','charge_id'),1));
select is(pg_temp.group_value('charges_minor'),'200000','report counts latest logical charge once, not both versions');
select is(public.doctor_practice_financial_source(pg_temp.id(21),'charge',pg_temp.value('charge1','id'),1)->'record'->>'amount_minor','149500','old charge source remains the original exact amount');
select is(pg_temp.report('charges',1,'all',null,null,(select(value->>'created_at')::timestamptz from results where name='charge1'))->>'total','1','UTC original issue at inclusive start is included');
select is(pg_temp.report('charges',1,'all',null,null,null,(select(value->>'created_at')::timestamptz from results where name='charge1'))->>'total','0','UTC original issue at exclusive end is excluded');
reset role;
-- A backdated correction must not move its cohort. Append, never rewrite immutable history.
insert into public.doctor_service_price_versions(id,service_id,revision,practice_id,location_id,doctor_user_id,label,unit_minor,currency,currency_exponent,actor_user_id)
values(pg_temp.id(750),pg_temp.value('price1','service_id'),3,pg_temp.id(21),pg_temp.id(31),pg_temp.id(1),'Synthetic visit service',210000,'EGP',2,pg_temp.id(1));
insert into public.doctor_visit_charge_versions(id,charge_id,revision,previous_id,practice_id,location_id,doctor_user_id,visit_id,visit_version,patient_id,price_id,service_id,label,unit_minor,quantity,amount_minor,currency,currency_exponent,reason,created_at,actor_user_id)
select pg_temp.id(751),pg_temp.value('charge1','charge_id'),3,pg_temp.value('charge2','id'),pg_temp.id(21),pg_temp.id(31),pg_temp.id(1),pg_temp.id(61),1,pg_temp.id(51),pg_temp.id(750),pg_temp.value('price1','service_id'),'Synthetic visit service',210000,1,210000,'EGP',2,'Synthetic backdated correction','2026-09-15T00:00:00Z',pg_temp.id(1);
set local role authenticated;select pg_temp.claim(1);
select is(pg_temp.report('charges',1,'all',null,null,(select(value->>'created_at')::timestamptz from results where name='charge1'))->>'total','1','backdated revision does not move original issue outside cohort');
select is(pg_temp.report()->'items'->0->>'source_revision','3','trace names exact current revision, not historical time ordering');
reset role;
-- Thirty additional synthetic charges across three separate currency/scale groups.
-- Keep their visit windows clear of the earlier day-one appointments; exclusion constraints remain enabled.
insert into public.doctor_service_price_versions(id,service_id,revision,practice_id,location_id,doctor_user_id,label,unit_minor,currency,currency_exponent,actor_user_id)
select pg_temp.id(800+n),pg_temp.id(810+n),1,pg_temp.id(21),pg_temp.id(31),pg_temp.id(1),'Synthetic paged service',100,case when n=2 then'USD'else'EGP'end,case when n=3 then 0 else 2 end,pg_temp.id(1)from generate_series(1,3)n;
insert into public.appointments(id,practice_id,doctor_user_id,location_id,patient_id,starts_at,ends_at,timezone,location_name,created_by)
select pg_temp.id(900+n),pg_temp.id(21),pg_temp.id(1),pg_temp.id(31),pg_temp.id(51),now()+interval'60 days'+n*interval'1 hour',now()+interval'60 days'+n*interval'1 hour'+interval'20 minutes','Etc/UTC','Synthetic clinic A',pg_temp.id(1)from generate_series(1,30)n;
insert into public.doctor_visit_charge_versions(id,charge_id,revision,previous_id,practice_id,location_id,doctor_user_id,visit_id,visit_version,patient_id,price_id,service_id,label,unit_minor,quantity,amount_minor,currency,currency_exponent,reason,created_at,actor_user_id)
select pg_temp.id(1000+n),pg_temp.id(1100+n),1,null,pg_temp.id(21),pg_temp.id(31),pg_temp.id(1),pg_temp.id(900+n),1,pg_temp.id(51),pg_temp.id(800+(n-1)/10+1),pg_temp.id(810+(n-1)/10+1),'Synthetic paged service',100,1,100,case when n between 11 and 20 then'USD'else'EGP'end,case when n>20 then 0 else 2 end,'Synthetic reporting cohort','2026-10-15T00:00:00Z',pg_temp.id(1)from generate_series(1,30)n;
set local role authenticated;select pg_temp.claim(1);
select is(pg_temp.report()->>'total','31','full population exceeds first page');
select is(jsonb_array_length(pg_temp.report()->'items'),25,'first contribution page is bounded');
select is(jsonb_array_length(pg_temp.report('charges',2)->'items'),6,'next contribution page has remaining exact sources');
select is(pg_temp.report()->'totals',pg_temp.report('charges',2)->'totals','summary totals do not change with source pagination');
select is(jsonb_array_length(pg_temp.report()->'totals'),3,'currency and decimal scale are independent grouping keys');
select is(pg_temp.group_value('charges_minor'),'211000','full EGP two-decimal total includes latest charge exactly once');
select is(pg_temp.group_value('charges_minor','USD',2),'1000','USD remains separate from EGP');
select is(pg_temp.group_value('charges_minor','EGP',0),'1000','EGP zero-decimal scale remains separate');
select is(pg_temp.report('refunds')->'totals',pg_temp.report()->'totals','metric selection narrows source trace, not full cohort totals');
select is(pg_temp.report('charges',1,'all','USD',2)->>'total','10','currency trace selects matching full-population source group');
select is(pg_temp.report('charges',1,'covered')->>'total','0','partial and uncollected charges are not falsely covered');
select is(pg_temp.report('charges',1,'attention')->>'total','1','pending refund keeps its charge in attention status');
reset role;
-- Deliberately incomplete synthetic import evidence: posted event without a receipt must be reported.
insert into public.doctor_practice_payment_intents(id,practice_id,location_id,doctor_user_id,patient_id,charge_id,charge_version_id,kind,amount_minor,currency,currency_exponent,reason,actor_user_id)
values(pg_temp.id(1201),pg_temp.id(21),pg_temp.id(31),pg_temp.id(1),pg_temp.id(51),pg_temp.id(1111),pg_temp.id(1011),'collection',50,'USD',2,'Synthetic deliberately incomplete import',pg_temp.id(1));
insert into public.doctor_practice_payment_events(intent_id,revision,state,reason_code,actor_user_id)values(pg_temp.id(1201),3,'posted','synthetic_accepted',pg_temp.id(1));
set local role authenticated;select pg_temp.claim(1);
select is(pg_temp.group_value('discrepancy_count','USD',2),'1','missing posted receipt is a visible discrepancy');
select is(pg_temp.group_value('collections_minor','USD',2),'0','posted status without immutable entry never invents a collection');
select is(pg_temp.report('discrepancies',1,'all','USD',2)->'items'->0->>'reason_code','posted_receipt_missing','discrepancy total traces the incomplete event');
select is(public.doctor_practice_financial_source(pg_temp.id(21),'intent_event',pg_temp.id(1201),3)->>'source_revision','3','discrepant immutable source is available without fabricating a receipt');
select throws_ok($$select pg_temp.report('charges',0)$$,'22023','DOCTOR_FINANCIAL_REPORT_QUERY_INVALID','invalid pagination is denied');
select throws_ok($$select pg_temp.report('charges',1,'all','USD',null)$$,'22023','DOCTOR_FINANCIAL_REPORT_QUERY_INVALID','currency and exponent must be paired');
select throws_ok($$select pg_temp.report('charges',1,'paid')$$,'22023','DOCTOR_FINANCIAL_REPORT_QUERY_INVALID','invented settled status is not accepted');
select throws_ok($$select pg_temp.report('charges',1,'all',null,null,now(),now())$$,'22023','DOCTOR_FINANCIAL_REPORT_QUERY_INVALID','empty or reversed date range is rejected');
select throws_ok($$select public.doctor_practice_financial_source(pg_temp.id(21),'ledger',(select(value#>>'{entry,id}')::uuid from results where name='posted'),1)$$,'22023','DOCTOR_FINANCIAL_SOURCE_QUERY_INVALID','immutable ledger source has no invented event revision');
select throws_ok($$select public.doctor_practice_financial_source(pg_temp.id(21),'charge',pg_temp.value('charge1','id'),2)$$,'22023','DOCTOR_FINANCIAL_SOURCE_QUERY_INVALID','source revision cannot replace selected charge snapshot');
select pg_temp.claim(2);
select throws_ok($$select pg_temp.report()$$,'42501','DOCTOR_BILLING_OWNER_REQUIRED','foreign doctor cannot read patient financial report');
select throws_ok($$select public.doctor_practice_financial_source(pg_temp.id(21),'charge',pg_temp.value('charge1','id'),1)$$,'42501','DOCTOR_BILLING_OWNER_REQUIRED','foreign doctor cannot inspect exact source');
select pg_temp.claim(3);
select throws_ok($$select pg_temp.report()$$,'42501','DOCTOR_BILLING_OWNER_REQUIRED','secretary administrative grants do not reveal practice money');
select pg_temp.claim(1);
select throws_ok($$select public.doctor_practice_financial_report(pg_temp.id(21),pg_temp.id(32))$$,'42501','DOCTOR_BILLING_OWNER_REQUIRED','foreign clinic is denied even under own practice selection');
select is(pg_temp.report()->>'saas_ledger_included','false','SaaS settlement remains a distinct ledger');
select is(pg_temp.report()->>'provider_payout','unavailable','no unavailable provider payout is equated with patient revenue');
select is(pg_temp.report()->>'tax_invoice_available','false','unreviewed tax report cannot assert official invoice availability');
reset role;
update public.doctor_edition_policy set mode='administrative_candidate',revision=revision+1,change_reason='Synthetic report history after expiry';
set local role authenticated;select pg_temp.claim(1);
select is(pg_temp.report()->>'total','31','inactive subscription retains authorized readonly historical report');
select is(public.doctor_practice_financial_source(pg_temp.id(21),'charge',pg_temp.value('charge1','id'),1)->'record'->>'amount_minor','149500','inactive owner can trace original immutable financial evidence');
reset role;
select ok(not has_function_privilege('authenticated','doctor_private.practice_financial_report_sources(uuid,uuid,timestamptz,timestamptz,text)','EXECUTE'),'unguarded source relation is not callable by client');
select ok(not has_function_privilege('anon','public.doctor_practice_financial_report(uuid,uuid,timestamptz,timestamptz,text,text,text,integer,integer)','EXECUTE'),'anonymous report execution is denied');
select ok(not has_function_privilege('service_role','public.doctor_practice_financial_source(uuid,text,uuid,integer,uuid)','EXECUTE'),'service facade cannot bypass exact source authority');
select is((select count(*)::integer from public.doctor_saas_periods),0,'report never creates SaaS authority');
select * from finish();rollback;
